#include "stdlib/stats/base/dists/signrank/quantile.h"
#include "stdlib/constants/float64/ln_two.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/exp.h"
#include <stdint.h>
#include <stdlib.h>

/**
* Evaluates the quantile function of the Wilcoxon signed rank test statistic with `n` observations.
*
* ## Notes
*
* -   Uses an iterative dynamic programming approach to compute the signed rank distribution weights. The table `w` of size `floor(n*(n+1)/4) + 1` stores the number of subsets of `{1,...,j}` summing to `i`, exploiting the distribution's symmetry around `n*(n+1)/4`.
*
* @param p   input value
* @param n   number of observations
* @return    evaluated quantile function
*
* @example
* double y = stdlib_base_dists_signrank_quantile( 0.8, 5 );
* // returns 11
*/
double stdlib_base_dists_signrank_quantile( const double p, const int32_t n ) {
	double pui;
	double *w;
	double r;
	int32_t u;
	int32_t c;
	int32_t q;
	int32_t e;
	int32_t k;
	int32_t j;
	int32_t i;

	if (
		stdlib_base_is_nan( p ) ||
		p < 0.0 ||
		p > 1.0 ||
		n <= 0
	) {
		return 0.0 / 0.0; // NaN
	}
	u = n * ( n + 1 ) / 2;
	if ( p == 0.0 ) {
		return 0.0;
	}
	if ( p == 1.0 ) {
		return (double)u;
	}

	c = u / 2;
	w = (double *)calloc( (size_t)( c + 1 ), sizeof( double ) );
	if ( w == NULL ) {
		return 0.0 / 0.0; // NaN
	}
	w[ 0 ] = 1.0;
	for ( j = 1; j <= n; j++ ) {
		e = j * ( j + 1 ) / 2;
		if ( e > c ) {
			e = c;
		}
		for ( i = e; i >= j; i-- ) {
			w[ i ] += w[ i - j ];
		}
	}

	pui = stdlib_base_exp( -(double)n * STDLIB_CONSTANT_FLOAT64_LN2 );
	r = 0.0;
	q = -1;
	while ( r < p ) {
		q += 1;
		k = ( q > c ) ? u - q : q;
		r += pui * w[ k ];
	}
	free( w );
	return (double)q;
}
